import styled from 'styled-components';

export const FooterContainer = styled.footer`
  padding: 2rem 0;
  border-top: 1px solid var(--border);
  text-align: center;
`;

export const FooterText = styled.p`
  font-size: 0.9rem;
  color: var(--secondary-text);
`;
